import itertools
D=[ # (grid, k)
 ([[8,0,0],[0,8,0],[0,0,0]],2),
 ([[0,0,3],[0,3,0],[3,0,0]],1),
 ([[5,0,0],[5,5,0],[5,0,0]],4),
 ([[5,5,5],[0,0,5],[0,0,0]],4)]
T=[[3,0,0],[3,3,3],[0,0,3]]
def feats(g):
    n=3
    col={(i,j) for i in range(n) for j in range(n) if g[i][j]}
    f={}
    f['count']=len(col)
    f['color']=next(iter({g[i][j] for i,j in col}))
    for i in range(n): f[f'r{i}']=sum((i,j) in col for j in range(n))
    for j in range(n): f[f'c{j}']=sum((i,j) in col for i in range(n))
    for d in range(-2,3): f[f'md{d}']=sum((i,i+d) in col for i in range(n))
    for d in range(0,5): f[f'ad{d}']=sum((i,d-i) in col for i in range(n) if 0<=d-i<n)
    def comps(nb):
        seen=set(); sizes=[]
        for p in col:
            if p in seen: continue
            st=[p]; s=0
            while st:
                q=st.pop()
                if q in seen: continue
                seen.add(q); s+=1
                for di,dj in nb:
                    r=(q[0]+di,q[1]+dj)
                    if r in col and r not in seen: st.append(r)
            sizes.append(s)
        return sizes
    s4=comps([(1,0),(-1,0),(0,1),(0,-1)])
    s8=comps([(di,dj) for di in(-1,0,1) for dj in(-1,0,1) if (di,dj)!=(0,0)])
    f['comp4']=len(s4); f['max4']=max(s4); f['comp8']=len(s8); f['max8']=max(s8)
    f['adj4']=sum((i+di,j+dj) in col for i,j in col for di,dj in [(1,0),(0,1)])
    f['adj8']=sum((i+di,j+dj) in col for i,j in col for di in(-1,0,1) for dj in(-1,0,1) if (di,dj)!=(0,0) and (i+di,j+dj) in col)
    f['diag_adj']=sum((i+1,j+1) in col or (i+1,j-1) in col for i,j in col)
    f['corners']=sum(p in col for p in [(0,0),(0,2),(2,0),(2,2)])
    f['center']=1 if (1,1) in col else 0
    f['border']=sum(i in(0,2) or j in(0,2) for i,j in col)
    f['interior']=len(col)-f['border']
    f['zeros'] = 9-len(col)
    return f
